class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        res = []
        for l in range(len(nums) - k + 1):
            windowMax = nums[l]
            for i in range(l, l + k):
                windowMax = max(windowMax, nums[i])
            res.append(windowMax)
        return res
